  color: var(--zv-text, #222222);
  width: 100%;
  box-sizing: border-box;
}

.wf-faq-section .wf-container {
  max-width: 920px;
  margin: 0 auto;
  padding: 0 24px;
  box-sizing: border-box;
  width: 100%;
}

