function getSizes(dir) {
  let codeSize = 0, mediaSize = 0, codeCount = 0, mediaCount = 0;
  function walk(d) {
    for (const f of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, f.name);
      if (f.isDirectory()) walk(p);
      else {
        const ext = path.extname(f.name).toLowerCase();
        const s = fs.statSync(p).size;
        if (['.jpg', '.jpeg', '.png', '.webp', '.gif', '.mp4', '.mov', '.avif'].includes(ext)) {
          mediaSize += s;
          mediaCount++;
        } else {
          codeSize += s;
          codeCount++;
        }
      }
    }
  }
  walk(dir);
  console.log({
    codeCount,
    codeSizeMB: (codeSize / (1024*1024)).toFixed(2),
    mediaCount,
    mediaSizeMB: (mediaSize / (1024*1024)).toFixed(2)
  });
}
