"/**
 * ZAVELYN BOTANAROOTS — REFINED MOBILE-FIRST DTC BUNDLE & SIZE UPSELL STYLES
 * Scoped strictly under .zv-botana-bundle-container
 * Forest Green: #17433C | Lime Green CTA: #C6FA54 | Warm Peach Pill: #FEF3E7
 */

.zv-botana-bundle-container {
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #17433C;
  width: 100%;
  max-width: 580px;
  margin: 0 auto;
  padding: 6px 0;
  -webkit-font-smoothing: antialiased;
}

.zv-botana-bundle-container * {
  box-sizing: border-box;
}

/* ==========================================================================
   1. BUNDLE SECTION HEADER (RESPONSIVE NO-OVERFLOW)
   ========================================================================== */
.zv-bundle-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  padding: 0 2px;
  gap: 8px;
  width: 100%;
}

.zv-bundle-header-title-wrap {
  flex: 1;
  min-width: 0;
}

.zv-bundle-header-label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.6px;
  color: #17433C;
  text-transform: uppercase;
  white-space: nowrap;
}

.zv-bundle-header-guarantee-wrap {
  flex-shrink: 0;
}

.zv-bundle-header-guarantee {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 700;
  color: #15803D;
  background: #F0FDF4;
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid #DCFCE7;
  white-space: nowrap;
  line-height: 1.2;
}

@media (max-width: 420px) {
  .zv-bundle-section-header {
    flex-wrap: wrap;
    gap: 6px;
  }
  .zv-bundle-header-label {
    font-size: 11.5px;
  }
  .zv-bundle-header-guarantee {
    font-size: 11px;
    padding: 2.5px 7px;
  }
}

