"  // Batch Add to Cart Action
  document.getElementById('zvSelfCareCtaBtn')?.addEventListener('click', async function() {
    const btn = this;
    btn.classList.add('loading');

    const itemsToAdd = [
      { id: DATA.vfit.id, quantity: 1 }
    ];
    if (state.eyeSelected) itemsToAdd.push({ id: DATA.eye.id, quantity: 1 });
    if (state.faceSelected) itemsToAdd.push({ id: DATA.face.id, quantity: 1 });

    try {
      const res = await fetch('/cart/add.js', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: itemsToAdd })
      });
      if (!res.ok) throw new Error('Add to cart failed');

      // Refresh & open Willa or Zavelyn Cart Drawer
      if (typeof window.willaOpenCartDrawer === 'function') {
        if (typeof window.willaRefreshCart === 'function') await window.willaRefreshCart();
        window.willaOpenCartDrawer();
        return;
      }
      const directDrawer = document.getElementById('willaCartDrawer');
      const directOverlay = document.getElementById('willaCartOverlay');
      if (directDrawer) {
        directDrawer.classList.add('active');
        if (directOverlay) directOverlay.classList.add('active');
        if (typeof window.willaRefreshCart === 'function') await window.willaRefreshCart();
        return;
      }
      window.location.href = '/checkout';
    } catch(err) {
      console.error(err);
      alert('Could not add to bag. Please try again.');
    } finally {
      btn.classList.remove('loading');
    }
  });"

